"""Pin the Python canonical encoder to the vectors generated by relic-crypto."""

from __future__ import annotations

import json
import uuid
from pathlib import Path

import pytest
from nacl.signing import SigningKey

from api import crypto

VECTORS = json.loads(
    (Path(__file__).resolve().parents[3] / "crates/relic-crypto/tests/vectors/auth-v1.json").read_text()
)


def _challenge(raw: dict) -> crypto.Challenge:
    return crypto.Challenge(
        challenge_id=uuid.UUID(hex=raw["challenge_id"]),
        nonce=bytes.fromhex(raw["nonce"]),
        audience=raw["audience"],
        expires_at_unix_micros=raw["expires_at_unix_micros"],
    )


def _check_signed_case(case: dict, record: bytes, domain: bytes) -> None:
    import hashlib

    assert case["signature_domain"].encode() == domain
    assert record.hex() == case["record"]
    digest = hashlib.sha256(record).digest()
    assert digest.hex() == case["digest"]
    message = crypto.signing_message(domain, digest)
    assert message.hex() == case["signing_message"]

    key = SigningKey(bytes.fromhex(case["seed"]))
    assert bytes(key.verify_key).hex() == case["public_key"]
    assert key.sign(message).signature.hex() == case["signature"]

    public_key = bytes.fromhex(case["public_key"])
    signature = bytes.fromhex(case["signature"])
    assert crypto.verify(public_key, domain, record, signature)
    assert not crypto.verify(public_key, domain, record + b"\x00", signature)
    assert not crypto.verify(public_key, domain + b"x", record, signature)


def test_vector_file_format():
    assert VECTORS["format"] == "relic-auth-vectors/1"


@pytest.mark.parametrize("case", VECTORS["encode_fields"])
def test_encode_fields(case):
    fields = [bytes.fromhex(field) for field in case["fields"]]
    assert crypto.encode_fields(case["domain"].encode(), fields).hex() == case["encoded"]


@pytest.mark.parametrize("case", VECTORS["login"], ids=lambda case: case["name"])
def test_login_vectors(case):
    inputs = case["inputs"]
    record = crypto.login_record(
        _challenge(inputs["challenge"]), bytes.fromhex(case["public_key"])
    )
    _check_signed_case(case, record, crypto.LOGIN_SIGNATURE_DOMAIN)


@pytest.mark.parametrize("case", VECTORS["registration"], ids=lambda case: case["name"])
def test_registration_vectors(case):
    inputs = case["inputs"]
    record = crypto.registration_record(
        _challenge(inputs["challenge"]),
        public_key=bytes.fromhex(case["public_key"]),
        requested_role=inputs["requested_role"],
        name=inputs["name"],
        organisation=inputs["organisation"],
        email=inputs["email"],
    )
    _check_signed_case(case, record, crypto.REGISTRATION_SIGNATURE_DOMAIN)


@pytest.mark.parametrize("case", VECTORS["registration_decision"], ids=lambda case: case["name"])
def test_registration_decision_vectors(case):
    inputs = case["inputs"]
    record = crypto.registration_decision_record(
        uuid.UUID(hex=inputs["registration_request_id"]),
        public_key=bytes.fromhex(inputs["applicant_public_key"]),
        requested_role=inputs["requested_role"],
        name=inputs["name"],
        organisation=inputs["organisation"],
        email=inputs["email"],
        moderator_id=uuid.UUID(hex=inputs["moderator_id"]),
        decision=inputs["decision"],
    )
    _check_signed_case(case, record, crypto.REGISTRATION_DECISION_SIGNATURE_DOMAIN)


def _revocation(inputs: dict) -> crypto.RevocationRequest:
    return crypto.RevocationRequest(
        revocation_id=uuid.UUID(hex=inputs["revocation_id"]),
        analyst_id=uuid.UUID(hex=inputs["analyst_id"]),
        target_type=inputs["target_type"],
        target_id=uuid.UUID(hex=inputs["target_id"]),
        reason=inputs["reason"],
    )


@pytest.mark.parametrize("case", VECTORS["revocation_request"], ids=lambda case: case["name"])
def test_revocation_request_vectors(case):
    record = crypto.revocation_request_record(_revocation(case["inputs"]))
    _check_signed_case(case, record, crypto.REVOCATION_REQUEST_SIGNATURE_DOMAIN)


@pytest.mark.parametrize("case", VECTORS["revocation_decision"], ids=lambda case: case["name"])
def test_revocation_decision_vectors(case):
    inputs = case["inputs"]
    record = crypto.revocation_decision_record(
        _revocation(inputs),
        moderator_id=uuid.UUID(hex=inputs["moderator_id"]),
        decision=inputs["decision"],
    )
    _check_signed_case(case, record, crypto.REVOCATION_DECISION_SIGNATURE_DOMAIN)


def _flag(inputs: dict) -> crypto.Flag:
    return crypto.Flag(
        flag_id=uuid.UUID(hex=inputs["flag_id"]),
        viewer_id=uuid.UUID(hex=inputs["viewer_id"]),
        target_type=inputs["target_type"],
        target_id=uuid.UUID(hex=inputs["target_id"]),
        note=inputs["note"],
    )


@pytest.mark.parametrize("case", VECTORS["flag"], ids=lambda case: case["name"])
def test_flag_vectors(case):
    record = crypto.flag_record(_flag(case["inputs"]))
    _check_signed_case(case, record, crypto.FLAG_SIGNATURE_DOMAIN)


@pytest.mark.parametrize("case", VECTORS["flag_response"], ids=lambda case: case["name"])
def test_flag_response_vectors(case):
    inputs = case["inputs"]
    record = crypto.flag_response_record(
        _flag(inputs),
        flag_response_id=uuid.UUID(hex=inputs["flag_response_id"]),
        analyst_id=uuid.UUID(hex=inputs["analyst_id"]),
        note=inputs["response_note"],
    )
    _check_signed_case(case, record, crypto.FLAG_RESPONSE_SIGNATURE_DOMAIN)


def test_small_order_public_key_is_rejected():
    # The identity point: any "signature" with R = identity and S = 0 would
    # verify under a non-strict verifier.
    identity = bytes([1] + [0] * 31)
    signature = identity + bytes(32)
    assert not crypto.verify(identity, b"RELIC:test:v1", b"anything", signature)


def test_wrong_lengths_are_rejected():
    assert not crypto.verify(b"\x00" * 31, b"d", b"r", b"\x00" * 64)
    assert not crypto.verify(b"\x00" * 32, b"d", b"r", b"\x00" * 63)
